public static void main(String[] args) {
// Create instances of Car and Motorcycle
Car myCar = new Car(50);  // Car with 50% fuel
Motorcycle myMotorcycle = new Motorcycle(20);  // Motorcycle with 20% fuel
myCar.drive();  // Should print: "Car is driving."
myMotorcycle.drive();  // Should print: "Motorcycle is driving."
